uniform float amzp_yaw2Deg;
uniform float amzp_pitch2Deg;
uniform float amzp_fov2Deg;
uniform float amzp_autoRotate2;
uniform float amzp_rotateSpeed2;
uniform float3 amzp_skyRotate;
uniform float amzp_linkCamSky;
uniform float amzp_bgFeatherEnabled;
uniform float amzp_bgFeather;
